import React,{useEffect,useRef,useState} from 'react';import{createRoot}from'react-dom/client';
import PhonePreview from '../../src/components/PhonePreview.jsx';import TypographyPanel from '../../src/components/TypographyPanel.jsx';
import{api}from'../../src/api/client.js';import{UIProvider}from'../../src/context/UIContext.jsx';
import{composeInvitationPreview}from'../../src/utils/mergePreviewOverride.js';
import{DUMMY_GALLERY_PHOTOS}from'../../src/config/dummyAssets.js';
import {TEMPLATES} from '../../src/config/templateRegistry.js';
import '../../src/styles/index.css';
const key='qa-immersia-final-isolated-v1',seed={id:'qa-local-only',slug:'qa-local-only',themeId:'garden-canvas',coupleProfile:{brideName:'Audit',groomName:'Lokal'},themeSettings:{typography:{metricsMode:'template'},characterSettings:{mode:'default'}},invitationFeatures:{rsvpEnabled:true,wishesEnabled:true,galleryEnabled:true,musicEnabled:true},galleryMedia:DUMMY_GALLERY_PHOTOS.map((url,i)=>({id:'photo-'+i,url,type:'photo',order:i})),wishes:[]};
const read=()=>{try{return JSON.parse(localStorage.getItem(key))||seed}catch{return seed}};
// This harness never writes to the API/Neon/R2. Backend transaction tests run separately.
api.patch=async(url,payload)=>{const saved=read();const next=url.endsWith('profile-content')?{...saved,coupleProfile:{...saved.coupleProfile,...payload.profile}}:{...saved,themeSettings:{...saved.themeSettings,typography:payload.typography}};localStorage.setItem(key,JSON.stringify(next));return{data:{...next,themeSettings:next.themeSettings}}};
function App(){const[inv,setInv]=useState(read),[live,setLive]=useState(null),[width,setWidth]=useState(390),[name,setName]=useState(inv.coupleProfile.brideName),[status,setStatus]=useState('Menunggu iframe'),host=useRef(null);
 useEffect(()=>{const report=()=>{const frame=host.current?.querySelector('iframe');if(!frame)return;const n=frame.clientWidth;setStatus(`${n<=450?'PASS':'FAIL'} — layar ${width}px, viewport undangan ${n}px`)};const observer=new ResizeObserver(report);observer.observe(host.current);const mutation=new MutationObserver(report);mutation.observe(host.current,{childList:true,subtree:true});window.addEventListener('message',report);report();return()=>{observer.disconnect();mutation.disconnect();window.removeEventListener('message',report)}},[width]);
 return <UIProvider><div style={{fontFamily:'sans-serif',background:'#f5f2e8',color:'#40553c',minHeight:'100dvh'}}><header style={{padding:16,display:'flex',gap:12,flexWrap:'wrap'}}>{[['HP',390],['iPad',768],['iPad Pro',1024],['Desktop',1440]].map(([label,w])=><button key={label} onClick={()=>setWidth(w)}>{label}</button>)}<select aria-label="Engine uji" value={inv.themeId} onChange={e=>setInv({...inv,themeId:e.target.value})}>{TEMPLATES.filter(t=>t.engine).map(t=><option key={t.id} value={t.id}>{t.name} — Engine {t.engine}</option>)}</select><strong role="status">{status}</strong></header><main style={{display:'flex',alignItems:'start',gap:16,padding:16}}><aside style={{width:280,flexShrink:0}}><p>Data uji lokal terpisah. Tidak mengubah undangan pengguna.</p><label>Nama uji<input aria-label="Nama uji" value={name} onChange={e=>setName(e.target.value)}/></label><button onClick={async()=>{const{data}=await api.patch('/invitations/me/profile-content',{profile:{brideName:name}});setInv(data)}}>Simpan nama uji</button><button onClick={()=>location.reload()}>Muat ulang data uji</button><TypographyPanel invitation={inv} mode="metrics" scopeOptions={['cover','hero','bride','groom']} activeSection="cover" onUpdated={setInv} onLivePreview={p=>setLive(p?.themeSettings?.typography||null)}/></aside><div style={{overflow:'auto',flex:1}}><div ref={host} data-audit-device style={{width,height:844,position:'relative'}}><PhonePreview invitation={composeInvitationPreview(inv,null,live)} editorPreview/></div></div></main></div></UIProvider>
}
createRoot(document.getElementById('root')).render(<App/>);
